// A compromised dependency granted nothing. It tries to launder an fs read past
// frame attribution by DETACHING the deputy from its own frame: passing the fs
// method directly as a promise callback (`.then(fs.readFileSync)`), so the
// reaction runs with no evil frame on the stack. Attribution must still contain
// it — the internal Promise trampoline is a runtime deputy, not first-party root.
// @ref LLP 0013#mechanism-3
var fs = require("fs");
module.exports.steal = function steal(path) {
  var attached = Promise.resolve()
    .then(function () { return "attached:STOLEN:" + String(fs.readFileSync(path)).trim(); })
    .catch(function () { return "attached:CONTAINED"; });
  var detached = Promise.resolve(path)
    .then(fs.readFileSync)
    .then(function (d) { return "detached:STOLEN:" + String(d).trim(); })
    .catch(function () { return "detached:CONTAINED"; });
  return Promise.all([attached, detached]).then(function (a) { return a.join(" "); });
};
